package com.training;

import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static com.training.RecommendationDecision.*;

/** Advisor mechanics with typed staff reviews; authorization/save-chain is tested by the Host suite. No network. */
public final class RecommendationCpaSemanticAdvisorTest {
    static int checks;
    static void ok(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
    @SuppressWarnings("unchecked") static Map<String,Object> obj(Object v){return (Map<String,Object>)v;}
    @SuppressWarnings("unchecked") static List<Map<String,Object>> rows(Object v){return (List<Map<String,Object>>)v;}
    static Candidate candidate(long id,String... texts){List<Evidence> es=new ArrayList<>();for(int i=0;i<texts.length;i++)es.add(evidence("private-org",id,"PROFILE_TOPIC","未核原文（仅本地）","local-only:"+id+":"+i,"local-version:"+i,texts[i]));return new Candidate(id,"合成人物"+id,"在库","合成私密地点",List.of(),Confirmation.CONFIRMED,Confirmation.CONFIRMED,List.of(),es);}
    static Snapshot snapshot(Candidate... c){return new Snapshot("private-org",hash("confirmed-advisor-synthetic"),new Request("面向新晋主管的项目管理实战课程","","2026-11-01","09:00","11:00","ONLINE",List.of()),List.of(c),true);}
    static Map<String,Object> claim(Evidence e,String assertion,String depth){return map("evidence_id",e.id(),"source_version",e.sourceVersion(),"topic","项目管理","role",assertion.equals("AFFIRMED")?"ASSISTANT":"LEAD_TEACHING","assertion",assertion,"audience","UNKNOWN","depth",depth,"limits",List.of("NONE_RECORDED"),"confirmed",true);}
    static Map<String,Object> review(Candidate c){List<Object> claims=new ArrayList<>();if(!c.evidence().isEmpty())claims.add(claim(c.evidence().get(0),"AFFIRMED","INTRODUCTORY"));if(c.evidence().size()>1)claims.add(claim(c.evidence().get(1),"DENIED","ADVANCED"));return map("schema_version","experience_review_v1","confirmed",true,"reviewed_entire_requirement",true,"reviewed_all_sources",true,"requirement",map("topic","项目管理","audience","NEW_SUPERVISORS","depth","PRACTICAL","limits",List.of("UNKNOWN")),"source_manifest",c.evidence().stream().map(e->map("evidence_id",e.id(),"source_version",e.sourceVersion())).toList(),"claims",claims);}
    static RecommendationCpaPayload.ReviewedProjection projection(Candidate c){return new RecommendationCpaPayload.ReviewedProjection(Map.of(c.id(),review(c)));}
    static Map<String,Object> answer(Map<String,Object> p,boolean select){List<Object> out=new ArrayList<>();for(var c:rows(p.get("candidates"))){var evidence=rows(c.get("evidence"));List<Object> refs=new ArrayList<>();if(select)for(var e:evidence)if(rows(e.get("claims")).stream().anyMatch(q->!"UNKNOWN".equals(q.get("assertion")))){refs.add(e.get("evidence_id"));break;}out.add(map("candidate_id",c.get("candidate_id"),"evidence_ids",refs,"reason_codes",List.of(refs.isEmpty()?"TOPIC_UNCLEAR":"TOPIC_RELATED")));}return map("suggestions",out);}
    static RecommendationCpaTransport.Result result(Map<String,Object> p){return new RecommendationCpaTransport.Result(answer(p,true),Map.of());}
    static RecommendationModelRunner.Advisory run(Snapshot s,RecommendationCpaPayload.ReviewedProjection p,RecommendationCpaAdvisor.Client client)throws Exception{return new RecommendationCpaAdvisor(true,client,System::currentTimeMillis).run(s,decide(s),p,()->{});}
    public static void main(String[] args)throws Exception {
        Candidate c=candidate(1,"项目管理由家长主讲。 电话REVIEW_PHONE_10","本人主讲项目管理？","尚未记录其他结构化事实的原文");Snapshot s=snapshot(c,candidate(2,"本人主讲项目管理。"));var verified=projection(c);
        AtomicInteger rawCalls=new AtomicInteger();var raw=new RecommendationCpaAdvisor(true,p->{rawCalls.incrementAndGet();return result(p);},System::currentTimeMillis).run(s,decide(s),()->{});
        ok("NO_CONFIRMED_EXPERIENCE".equals(raw.metadata().get("status"))&&rawCalls.get()==0,"raw prose and old transport/service confirmations never become experience facts");
        ok(((Number)obj(raw.metadata().get("usageBudget")).get("used")).intValue()==0,"unreviewed privacy refusal consumes no service-cycle quota");
        AtomicInteger calls=new AtomicInteger();var accepted=run(s,verified,p->{calls.incrementAndGet();String wire=Json.write(p);for(String secret:List.of("家长主讲","REVIEW_PHONE_10","本人主讲","合成人物","private-org","local-only","local-version","合成私密地点","teacher:","ev:"))ok(!wire.contains(secret),"wire excludes raw/private marker "+secret);return result(p);});
        ok(calls.get()==1&&"COMPLETE".equals(accepted.metadata().get("status")),"typed confirmed unit positive calls once");var a=accepted.suggestions().get(c.id());var all=rows(a.get("localEvidence"));
        ok(all.size()==3&&((List<?>)a.get("evidenceIds")).size()==1,"all reviewed sources survive model subset choice");ok(Json.write(all.get(1).get("claims")).contains("DENIED"),"unselected denied event is retained");ok(rows(all.get(2).get("claims")).isEmpty(),"reviewed source without structured claim remains explicitly empty");ok("STAFF_CONFIRMED".equals(all.get(0).get("verification")),"local verification status explicit");
        ok(rows(accepted.suggestions().get("teacher:2").get("localEvidence")).isEmpty(),"unreviewed candidate receives no inferred facts");
        var abstain=run(s,verified,p->new RecommendationCpaTransport.Result(answer(p,false),Map.of()));ok(rows(abstain.suggestions().get(c.id()).get("localEvidence")).size()==3,"AI abstention cannot hide reviewed records");
        for(String mode:List.of("EMPTY_SOURCE","FOREIGN","EXTRA","TIMEOUT","AUTH")){
            AtomicInteger count=new AtomicInteger();var failed=run(s,verified,p->{count.incrementAndGet();if(mode.equals("TIMEOUT"))throw new RecommendationCpaTransport.SafeFailure("TIMED_OUT");if(mode.equals("AUTH"))throw new RecommendationCpaTransport.SafeFailure("AUTH_REQUIRED");var response=answer(p,true);var row=rows(response.get("suggestions")).get(0);if(mode.equals("EXTRA"))row.put("qualification","qualified");else row.put("evidence_ids",List.of(mode.equals("EMPTY_SOURCE")?rows(rows(p.get("candidates")).get(0).get("evidence")).get(2).get("evidence_id"):"E48"));return new RecommendationCpaTransport.Result(response,Map.of());});
            ok((mode.equals("TIMEOUT")?"TIMED_OUT":mode.equals("AUTH")?"AUTH_REQUIRED":"INVALID_OUTPUT").equals(failed.metadata().get("status"))&&failed.suggestions().isEmpty(),"safe failure "+mode);ok(count.get()==1,"zero retry "+mode);ok(((Number)obj(failed.metadata().get("usageBudget")).get("used")).intValue()==1&&((Number)obj(failed.metadata().get("usageBudget")).get("remaining")).intValue()==29,"failed sent request still consumes reservation "+mode);
        }
        AtomicInteger staleCalls=new AtomicInteger();var stale=review(c);rows(stale.get("source_manifest")).get(2).put("source_version","other-version");var no=run(s,new RecommendationCpaPayload.ReviewedProjection(Map.of(c.id(),stale)),p->{staleCalls.incrementAndGet();return result(p);});ok(!"COMPLETE".equals(no.metadata().get("status"))&&staleCalls.get()==0,"source version guard before client");
        // Valid cardinalities and enums: all 48 sources and 24 claims are preserved; only byte size is excessive.
        List<Candidate> largeCandidates=new ArrayList<>();Map<String,Map<String,Object>> largeReviews=new LinkedHashMap<>();
        for(int i=1;i<=6;i++){Candidate large=candidate(i,"合成来源1","合成来源2","合成来源3","合成来源4","合成来源5","合成来源6","合成来源7","合成来源8");largeCandidates.add(large);Map<String,Object> r=review(large);r.put("requirement",map("topic","项目管理","audience","UNKNOWN","depth","UNKNOWN","limits",List.of("REQUIRE_LEAD_TEACHING","REQUIRE_TEACHING_EXPERIENCE","REQUIRE_PRACTICAL_EXPERIENCE","EXCLUDE_THEORY_ONLY","INTRODUCTORY_ONLY","ONLY_INCLUDED_TOPICS")));List<Map<String,Object>> claims=new ArrayList<>();for(int j=0;j<4;j++){Map<String,Object> q=claim(large.evidence().get(j),"LIMITED","INTRODUCTORY");q.put("audience","EXPERIENCED_PROJECT_MANAGERS");q.put("limits",List.of("INTRODUCTORY_ONLY","LIMITED_LEAD_EXPERIENCE","LIMITED_TEACHING_EXPERIENCE","ROLE_SCOPE_UNCLEAR"));claims.add(q);}r.put("claims",claims);largeReviews.put(large.id(),r);}
        Snapshot largeSnapshot=snapshot(largeCandidates.toArray(Candidate[]::new));var largeProjection=new RecommendationCpaPayload.ReviewedProjection(largeReviews);var largePrepared=RecommendationCpaPayload.prepare(largeSnapshot,decide(largeSnapshot),largeProjection);int largeBytes=Json.write(largePrepared.request()).getBytes(java.nio.charset.StandardCharsets.UTF_8).length;AtomicInteger largeCalls=new AtomicInteger();var tooLarge=run(largeSnapshot,largeProjection,p->{largeCalls.incrementAndGet();return result(p);});
        ok(largeBytes==20046&&largePrepared.evidenceAliases().size()==48&&Integer.valueOf(24).equals(largePrepared.filter().get("claimCount"))&&"INPUT_LIMIT".equals(tooLarge.metadata().get("status"))&&"RULES".equals(tooLarge.metadata().get("source"))&&Integer.valueOf(0).equals(tooLarge.metadata().get("attempts"))&&largeCalls.get()==0&&tooLarge.suggestions().isEmpty(),"valid 20046-byte reviewed input refuses before client with all 48 sources and 24 claims intact");
        Map<String,Map<String,Object>> byteReviews=new LinkedHashMap<>();for(int i=0;i<4;i++)byteReviews.put(largeCandidates.get(i).id(),largeReviews.get(largeCandidates.get(i).id()));
        Snapshot byteSnapshot=snapshot(largeCandidates.subList(0,4).toArray(Candidate[]::new));var byteProjection=new RecommendationCpaPayload.ReviewedProjection(byteReviews);
        int requestBytes=Json.write(RecommendationCpaPayload.prepare(byteSnapshot,decide(byteSnapshot),byteProjection).request()).getBytes(java.nio.charset.StandardCharsets.UTF_8).length;
        ok(requestBytes<=16384&&requestBytes*4<=65536&&requestBytes*5>65536,"four valid requests fit byte window, fifth exceeds bytes before six calls");
        AtomicLong byteClock=new AtomicLong(100000);AtomicInteger byteCalls=new AtomicInteger();var byteLimited=new RecommendationCpaAdvisor(true,p->{byteCalls.incrementAndGet();return result(p);},byteClock::get);
        for(int i=0;i<4;i++)ok("COMPLETE".equals(byteLimited.run(byteSnapshot,decide(byteSnapshot),byteProjection,()->{}).metadata().get("status")),"valid byte-window request "+i);
        var byteDenied=byteLimited.run(byteSnapshot,decide(byteSnapshot),byteProjection,()->{});var byteBudget=obj(byteDenied.metadata().get("usageBudget"));
        ok("USAGE_LIMIT".equals(byteDenied.metadata().get("status"))&&"MINUTE_BYTES".equals(byteBudget.get("blockedBy"))&&byteCalls.get()==4,"byte reservation refusal reports actual gate and never calls client");
        ok(((Number)byteBudget.get("remaining")).intValue()==26&&((Number)byteBudget.get("minuteRemaining")).intValue()==2&&((Number)byteBudget.get("minuteBytesRemaining")).intValue()==65536-requestBytes*4,"remaining calls do not conceal exhausted request byte capacity");
        byteClock.addAndGet(60000);var byteRecovered=byteLimited.run(byteSnapshot,decide(byteSnapshot),byteProjection,()->{});
        ok("COMPLETE".equals(byteRecovered.metadata().get("status"))&&byteCalls.get()==5&&((Number)obj(byteRecovered.metadata().get("usageBudget")).get("used")).intValue()==5,"minute byte window recovers without resetting total calls");
        AtomicLong clock=new AtomicLong(100000);AtomicInteger limitedCalls=new AtomicInteger();var limited=new RecommendationCpaAdvisor(true,p->{limitedCalls.incrementAndGet();return result(p);},clock::get);
        for(int i=0;i<6;i++)ok("COMPLETE".equals(limited.run(s,decide(s),verified,()->{}).metadata().get("status")),"minute budget allows call "+i);ok("USAGE_LIMIT".equals(limited.run(s,decide(s),verified,()->{}).metadata().get("status"))&&limitedCalls.get()==6,"seventh call blocked without retry");
        for(int minute=1;minute<5;minute++){clock.addAndGet(60000);for(int call=0;call<6;call++){var charged=limited.run(s,decide(s),verified,()->{});Map<String,Object> budget=obj(charged.metadata().get("usageBudget"));int used=minute*6+call+1;ok(((Number)budget.get("used")).intValue()==used&&((Number)budget.get("remaining")).intValue()==30-used&&((Number)budget.get("limit")).intValue()==30,"actual service-cycle quota after reservation "+used);}}
        clock.addAndGet(60000);var exhausted=limited.run(s,decide(s),verified,()->{});Map<String,Object> spent=obj(exhausted.metadata().get("usageBudget"));
        ok("USAGE_LIMIT".equals(exhausted.metadata().get("status"))&&limitedCalls.get()==30&&"SERVICE_TOTAL".equals(spent.get("blockedBy"))&&((Number)spent.get("remaining")).intValue()==0,"31st request remains blocked after a minute without calling client");
        ok("CURRENT_SERVICE_CYCLE".equals(spent.get("scope"))&&spent.get("cycleStartedAt").equals("1970-01-01T00:01:40Z"),"quota identifies actual current startup cycle");
        CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);AtomicInteger concurrentCalls=new AtomicInteger();var serial=new RecommendationCpaAdvisor(true,p->{concurrentCalls.incrementAndGet();entered.countDown();if(!release.await(5,TimeUnit.SECONDS))throw new AssertionError("release timeout");return result(p);},System::currentTimeMillis);ExecutorService worker=Executors.newSingleThreadExecutor();Future<RecommendationModelRunner.Advisory> pending=worker.submit(()->serial.run(s,decide(s),verified,()->{}));try{ok(entered.await(5,TimeUnit.SECONDS),"first client entered");var busy=serial.run(s,decide(s),verified,()->{});ok("BUSY".equals(busy.metadata().get("status"))&&"CONCURRENT_REQUEST".equals(obj(busy.metadata().get("usageBudget")).get("blockedBy"))&&concurrentCalls.get()==1,"concurrency remains one, no queue and exact gate reported");}finally{release.countDown();worker.shutdown();}ok("COMPLETE".equals(pending.get(5,TimeUnit.SECONDS).metadata().get("status")),"in-flight first completes");ok(worker.awaitTermination(5,TimeUnit.SECONDS),"owned worker stopped");
        var disabled=new RecommendationCpaAdvisor(false,p->{throw new AssertionError("disabled called");},System::currentTimeMillis);ok("DISABLED".equals(disabled.run(s,decide(s),verified,()->{}).metadata().get("status")),"default disabled remains effective");
        System.out.println("RecommendationCpaSemanticAdvisorTest: "+checks+" checks passed; typed review unit boundary only; Host suite proves saved authorization; no network.");
    }
}
